DO $patch$ DECLARE s text; BEGIN
 s:=pg_get_functiondef('public.fin_project_expense_lists()'::regprocedure);s:=replace(s,'WHEN e.workflow_version=2 THEN greatest(0,round','WHEN e.workflow_version=2 AND e.eur_amount IS NULL THEN NULL WHEN e.workflow_version=2 THEN greatest(0,round');s:=replace(s,'CASE WHEN e.workflow_version=2 THEN greatest(0,e.eur_amount','CASE WHEN e.workflow_version=2 AND e.eur_amount IS NULL THEN NULL WHEN e.workflow_version=2 THEN greatest(0,e.eur_amount');EXECUTE s;
 s:=pg_get_functiondef('public.pe_invoice_from_expenses(jsonb,jsonb)'::regprocedure);IF position('IF v_expense.id IS NULL OR v_expense.workflow_version<>2' in s)=0 THEN RAISE EXCEPTION 'Missing expense invoice boundary'; END IF;s:=replace(s,'IF v_expense.id IS NULL OR v_expense.workflow_version<>2','IF v_expense.invoiced_at IS NOT NULL THEN RAISE EXCEPTION ''Expense already has a manually recorded invoice reference''; END IF; IF v_expense.id IS NULL OR v_expense.workflow_version<>2');EXECUTE s;
END $patch$;